def median(nums):
    if not nums:
        raise ValueError('Empty list')
    sorted_nums = sorted(nums)
    n = len(sorted_nums)
    mid = n // 2
    if n % 2 == 1:
        return sorted_nums[mid]
    else:
        return (sorted_nums[mid - 1] + sorted_nums[mid]) / 2

# Example:
# median([3, 1, 4, 2]) -> 2.5
# median([3, 1, 4]) -> 3

