"""Returns the nth Fibonacci number using iterative dynamic programming.
Runs in O(n) time and O(1) space by keeping only the last two values."""
def fibonacci(n):
    if n <= 1:
        return n
    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b
